using System;
using System.Drawing;
using System.Windows.Forms;

namespace SPI_Data_Comp_Tool
{
    /// <summary>
    /// One look for every window (Windows 11 style): light-grey window, white group boxes,
    /// flat buttons with a thin border, one blue main button, Segoe UI 9, the app icon.
    /// Call UiTheme.Apply(this, mainButton) at the end of a form's constructor.
    /// Layout (where controls sit) lives in the designer files, generated by tools/layout_gen.py.
    /// </summary>
    internal static class UiTheme
    {
        public static readonly Color WindowBack = Color.FromArgb(243, 243, 243);
        public static readonly Color CardBack = Color.White;
        public static readonly Color Border = Color.FromArgb(200, 200, 200);
        public static readonly Color Accent = Color.FromArgb(0, 95, 184);
        public static readonly Color AccentHover = Color.FromArgb(0, 84, 163);
        public static readonly Color TextColor = Color.FromArgb(26, 26, 26);
        public static readonly Color MutedText = Color.FromArgb(90, 90, 90);

        private static Icon appIcon;

        /// <summary>The app icon from the exe, so every window shows the same icon.</summary>
        public static void SetIcon(Form form)
        {
            try
            {
                if (appIcon == null) appIcon = Icon.ExtractAssociatedIcon(Application.ExecutablePath);
                if (appIcon != null) form.Icon = appIcon;
            }
            catch (Exception)
            {
                // keep the form's own icon if the exe icon cannot be read
            }
        }

        public static void Apply(Form form, params Button[] mainButtons)
        {
            SetIcon(form);
            form.BackColor = WindowBack;
            form.ForeColor = TextColor;
            Style(form.Controls);
            foreach (var b in mainButtons)
            {
                if (b == null) continue;
                b.BackColor = Accent;
                b.ForeColor = Color.White;
                b.FlatAppearance.BorderColor = Accent;
                b.FlatAppearance.MouseOverBackColor = AccentHover;
                b.Font = new Font(b.Font, FontStyle.Bold);
            }
        }

        private static void Style(Control.ControlCollection controls)
        {
            foreach (Control c in controls)
            {
                switch (c)
                {
                    case GroupBox g:
                        g.BackColor = CardBack;
                        break;
                    case Button b:
                        b.FlatStyle = FlatStyle.Flat;
                        b.UseVisualStyleBackColor = false;
                        b.BackColor = CardBack;
                        b.ForeColor = TextColor;
                        b.FlatAppearance.BorderColor = Border;
                        b.FlatAppearance.MouseOverBackColor = Color.FromArgb(235, 243, 252);
                        b.Cursor = Cursors.Hand;
                        break;
                    case TextBox t:
                        t.BorderStyle = BorderStyle.FixedSingle;
                        break;
                    case ListBox l:
                        l.BorderStyle = BorderStyle.FixedSingle;
                        l.IntegralHeight = false;
                        break;
                    case RichTextBox r:
                        r.BorderStyle = BorderStyle.FixedSingle;
                        break;
                    case TableLayoutPanel _:
                    case FlowLayoutPanel _:
                        c.BackColor = Color.Transparent;
                        break;
                    case CheckBox cb:
                        cb.UseVisualStyleBackColor = true;
                        break;
                }
                if (c.HasChildren) Style(c.Controls);
            }
        }
    }
}
